def p(text='',bold=False,center=False,indent=True,after=2):
    x=doc.add_paragraph()
    x.paragraph_format.space_after=Pt(after)
    if center: x.alignment=WD_ALIGN_PARAGRAPH.CENTER
    else:
        x.alignment=WD_ALIGN_PARAGRAPH.THAI_JUSTIFY if indent else WD_ALIGN_PARAGRAPH.LEFT
        if indent: x.paragraph_format.first_line_indent=Inches(.5)
    x.add_run(text).bold=bold
    return x
def h(text): return doc.add_paragraph(text,'Heading 2')
def chapter(n,title):
    x=doc.add_paragraph(f'บทที่ {n}\n{title}','Heading 1'); x.alignment=WD_ALIGN_PARAGRAPH.CENTER
def page():
    x=doc.add_paragraph(); x.paragraph_format.space_after=Pt(0); x.paragraph_format.space_before=Pt(0)
    x.paragraph_format.line_spacing=Pt(1); x.add_run().add_break(WD_BREAK.PAGE)
    x.runs[0].font.size=Pt(1)
def title(text):
    x=doc.add_paragraph(text,'Heading 1'); x.alignment=WD_ALIGN_PARAGRAPH.CENTER
def table(headers,rows,widths):
    t=doc.add_table(rows=1,cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.autofit=False
    for c,w in zip(t.columns,widths): c.width=Cm(w)
    pr=t._tbl.tblPr
    borders=OxmlElement('w:tblBorders')
    for e in ['top','left','bottom','right','insideH','insideV']:
        b=OxmlElement('w:'+e); b.set(qn('w:val'),'single'); b.set(qn('w:sz'),'4'); b.set(qn('w:color'),'D9D9D9'); borders.append(b)
    pr.append(borders)
    for row in [t.rows[0]]:
        rep=OxmlElement('w:tblHeader'); row._tr.get_or_add_trPr().append(rep)
    for row,vals in [(t.rows[0],headers)]+[(t.add_row(),r) for r in rows]:
        cant=OxmlElement('w:cantSplit'); row._tr.get_or_add_trPr().append(cant)
        for i,(c,txt) in enumerate(zip(row.cells,vals)):
            c.width=Cm(widths[i]); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            cp=c._tc.get_or_add_tcPr(); margins=OxmlElement('w:tcMar')
            for e,v in [('top',30),('bottom',30),('left',90),('right',90)]:
                a=OxmlElement('w:'+e); a.set(qn('w:w'),str(v)); a.set(qn('w:type'),'dxa'); margins.append(a)
            cp.append(margins)
            x=c.paragraphs[0]; x.paragraph_format.space_after=Pt(0); x.paragraph_format.line_spacing=1
            x.alignment=WD_ALIGN_PARAGRAPH.LEFT
            x.add_run(txt)
            if row is t.rows[0]: pass
    for c in t.rows[0].cells:
        sh=OxmlElement('w:shd'); sh.set(qn('w:fill'),'EEEEEE'); c._tc.get_or_add_tcPr().append(sh)
        for r in c.paragraphs[0].runs: r.bold=True
    spacer=doc.add_paragraph(); spacer.paragraph_format.space_after=Pt(0); spacer.paragraph_format.line_spacing=Pt(2)
    return t
def caption(s):
    x=p(s,bold=True,indent=False,after=4); x.paragraph_format.keep_with_next=True
def field(x,code,text=''):
    b=OxmlElement('w:fldChar'); b.set(qn('w:fldCharType'),'begin'); x.add_run()._r.append(b)
    ins=OxmlElement('w:instrText'); ins.set(qn('xml:space'),'preserve'); ins.text=code; x.add_run()._r.append(ins)
    sep=OxmlElement('w:fldChar'); sep.set(qn('w:fldCharType'),'separate'); x.add_run()._r.append(sep)
    x.add_run(text)
    e=OxmlElement('w:fldChar'); e.set(qn('w:fldCharType'),'end'); x.add_run()._r.append(e)

